<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/bootstrap.php';
use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
use School\Services\AuditService;

SchoolAuth::requireLogin();
$user = SchoolAuth::user();
$role = school_current_role($user);
$mayConfigure = SchoolAuth::hasPermission('school.manage');
$mayEnter = SchoolAuth::hasPermission('results.marks.enter');
$mayReview = SchoolAuth::hasPermission('results.review');
$mayApprove = SchoolAuth::hasPermission('results.approve');
$mayPublish = SchoolAuth::hasPermission('results.publish');
if (!$mayConfigure && !$mayEnter && !$mayReview) { http_response_code(403); exit('Academic access is not permitted.'); }
$pdo = SchoolDatabase::connection();
$error = '';
$flash = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!SchoolAuth::verifyCsrf()) $error = 'Your session expired. Please try again.';
    else try {
        $action = (string)($_POST['action'] ?? '');
        if ($action === 'create_exam' && $mayConfigure) {
            $termId = (int)($_POST['term_id'] ?? 0); $name = trim((string)($_POST['name'] ?? '')); $type = trim((string)($_POST['type'] ?? ''));
            $starts = (string)($_POST['starts_on'] ?? ''); $ends = (string)($_POST['ends_on'] ?? '');
            if (!$termId || $name === '' || $type === '') throw new RuntimeException('Choose a term and enter the assessment name and type.');
            if (($starts !== '' && !preg_match('/^\d{4}-\d{2}-\d{2}$/', $starts)) || ($ends !== '' && !preg_match('/^\d{4}-\d{2}-\d{2}$/', $ends)) || ($starts !== '' && $ends !== '' && $ends < $starts)) throw new RuntimeException('Enter valid assessment dates in chronological order.');
            $q = $pdo->prepare('INSERT INTO examinations (term_id,name,type,workflow_status,starts_on,ends_on) VALUES (:term,:name,:type,\'draft\',:starts,:ends)');
            $q->execute(['term'=>$termId,'name'=>$name,'type'=>$type,'starts'=>$starts ?: null,'ends'=>$ends ?: null]);
            $id=(int)$pdo->lastInsertId(); (new AuditService())->record((int)$user['id'],'assessment.exam.create','examinations',$id,['type'=>$type]); $flash='Assessment period created as a draft.';
        } elseif ($action === 'create_assessment' && $mayConfigure) {
            $examId=(int)($_POST['examination_id']??0);$subjectId=(int)($_POST['subject_id']??0);$classId=(int)($_POST['class_group_id']??0);$max=(float)($_POST['max_mark']??0);$weight=(float)($_POST['weight']??1);
            if(!$examId||!$subjectId||!$classId||$max<=0||$weight<=0)throw new RuntimeException('Choose an exam, subject and class, with positive maximum mark and weight.');
            $check=$pdo->prepare("SELECT e.workflow_status,t.academic_year_id,c.academic_year_id class_year,c.level class_level,s.level subject_level FROM examinations e JOIN terms t ON t.id=e.term_id JOIN class_groups c ON c.id=:class JOIN subjects s ON s.id=:subject AND s.active=1 WHERE e.id=:exam");$check->execute(['class'=>$classId,'subject'=>$subjectId,'exam'=>$examId]);$exam=$check->fetch();
            if(!$exam||$exam['workflow_status']!=='draft'||(int)$exam['academic_year_id']!==(int)$exam['class_year'])throw new RuntimeException('The class and assessment must belong to the same academic year and the assessment must be draft.');
            if($exam['subject_level']!=='both'&&$exam['subject_level']!==$exam['class_level'])throw new RuntimeException('That subject is not available for the selected class level.');
            $q=$pdo->prepare('INSERT INTO assessments (examination_id,subject_id,class_group_id,max_mark,weight) VALUES (:exam,:subject,:class,:max,:weight)');$q->execute(['exam'=>$examId,'subject'=>$subjectId,'class'=>$classId,'max'=>$max,'weight'=>$weight]);
            $id=(int)$pdo->lastInsertId();(new AuditService())->record((int)$user['id'],'assessment.create','assessments',$id);$flash='Subject assessment added.';
        } elseif ($action === 'save_marks' && $mayEnter) {
            $assessmentId=(int)($_POST['assessment_id']??0);$marks=$_POST['marks']??[];if(!$assessmentId||!is_array($marks)||!$marks)throw new RuntimeException('Choose an assessment and enter marks.');
            $q=$pdo->prepare("SELECT a.*,e.workflow_status,e.id exam_id,t.academic_year_id FROM assessments a JOIN examinations e ON e.id=a.examination_id JOIN terms t ON t.id=e.term_id WHERE a.id=:id");$q->execute(['id'=>$assessmentId]);$assessment=$q->fetch();
            if(!$assessment||$assessment['workflow_status']!=='open')throw new RuntimeException('Marks can only be entered while an assessment is open.');
            if(in_array($role,['class_teacher','subject_teacher'],true)){$q=$pdo->prepare("SELECT COUNT(*) FROM teacher_assignments ta JOIN staff s ON s.id=ta.staff_id WHERE s.user_id=:user AND s.employment_status='active' AND ta.class_group_id=:class AND ta.academic_year_id=:year AND ta.subject_id=:subject AND ta.ended_at IS NULL");$q->execute(['user'=>(int)$user['id'],'class'=>(int)$assessment['class_group_id'],'year'=>(int)$assessment['academic_year_id'],'subject'=>(int)$assessment['subject_id']]);if(!(int)$q->fetchColumn())throw new RuntimeException('You are not assigned to this class and subject.');}
            $roster=$pdo->prepare("SELECT s.id FROM students s JOIN enrollments en ON en.student_id=s.id WHERE en.class_group_id=:class AND en.academic_year_id=:year AND en.status='active' AND s.status='active'");$roster->execute(['class'=>(int)$assessment['class_group_id'],'year'=>(int)$assessment['academic_year_id']]);$valid=array_fill_keys(array_map('intval',array_column($roster->fetchAll(),'id')),true);
            if(count($marks)!==count($valid))throw new RuntimeException('Submit one mark for every active student in the class register.');
            foreach($marks as $sid=>$value)if(!isset($valid[(int)$sid])||!is_numeric($value)||(float)$value<0||(float)$value>(float)$assessment['max_mark'])throw new RuntimeException('Each mark must belong to an active learner in the class and be between 0 and '.num($assessment['max_mark']).'.');
            SchoolDatabase::transaction(function(PDO $pdo)use($marks,$assessmentId,$assessment,$user):void{
                $find=$pdo->prepare('SELECT id,current_version,status FROM results WHERE assessment_id=:assessment AND student_id=:student FOR UPDATE');$insert=$pdo->prepare("INSERT INTO results (assessment_id,student_id,mark,status,current_version) VALUES (:assessment,:student,:mark,'draft',0) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)");$update=$pdo->prepare("UPDATE results SET mark=:mark,status='submitted',current_version=:version WHERE id=:id");$version=$pdo->prepare('INSERT INTO result_versions (result_id,version,mark,changed_by,reason) VALUES (:result,:version,:mark,:user,\'Submitted assessment marks\')');$count=0;
                foreach($marks as $studentId=>$raw){$mark=(float)$raw;$insert->execute(['assessment'=>$assessmentId,'student'=>(int)$studentId,'mark'=>$mark]);$resultId=(int)$pdo->lastInsertId();$find->execute(['assessment'=>$assessmentId,'student'=>(int)$studentId]);$existing=$find->fetch();if($existing&&$existing['status']==='published')throw new RuntimeException('Published marks cannot be edited.');$next=(int)($existing['current_version']??0)+1;$update->execute(['mark'=>$mark,'version'=>$next,'id'=>$resultId]);$version->execute(['result'=>$resultId,'version'=>$next,'mark'=>$mark,'user'=>(int)$user['id']]);$count++;}
                (new AuditService())->record((int)$user['id'],'assessment.marks.submit','assessments',$assessmentId,['students'=>$count]);
            });$flash='Marks saved and submitted for review.';
        } elseif ($action === 'transition_exam') {
            $examId=(int)($_POST['examination_id']??0);$to=(string)($_POST['to_status']??'');$allowed=['open'=>$mayConfigure,'under_review'=>$mayReview,'approved'=>$mayApprove,'published'=>$mayPublish];if(!$examId||empty($allowed[$to])){http_response_code(403);throw new RuntimeException('You cannot perform that assessment action.');}
            SchoolDatabase::transaction(function(PDO $pdo)use($examId,$to,$user):void{
                $q=$pdo->prepare('SELECT workflow_status FROM examinations WHERE id=:id FOR UPDATE');$q->execute(['id'=>$examId]);$from=$q->fetchColumn();if($from===false)throw new RuntimeException('Assessment not found.');
                if($to==='open'&&$from!=='draft')throw new RuntimeException('Only a draft assessment can be opened.');
                if($to==='under_review'){if(!in_array($from,['open','under_review'],true))throw new RuntimeException('Only open assessments can enter review.');$q=$pdo->prepare("SELECT COUNT(*) FROM assessments a JOIN results r ON r.assessment_id=a.id WHERE a.examination_id=:id AND r.status='submitted'");$q->execute(['id'=>$examId]);if(!(int)$q->fetchColumn())throw new RuntimeException('No submitted marks are ready for review.');}
                if($to==='approved'){
                    if($from!=='under_review')throw new RuntimeException('The assessment must be under review first.');
                    $q=$pdo->prepare("SELECT COUNT(*) FROM assessments a JOIN examinations e ON e.id=a.examination_id JOIN terms t ON t.id=e.term_id WHERE a.examination_id=:id AND (SELECT COUNT(*) FROM enrollments en JOIN students st ON st.id=en.student_id WHERE en.class_group_id=a.class_group_id AND en.academic_year_id=t.academic_year_id AND en.status='active' AND st.status='active')<>(SELECT COUNT(*) FROM results r WHERE r.assessment_id=a.id AND r.status='submitted')");$q->execute(['id'=>$examId]);if((int)$q->fetchColumn())throw new RuntimeException('Complete mark entry for every active student in each subject before approving.');
                    $q=$pdo->prepare("SELECT COUNT(*) FROM assessments WHERE examination_id=:id");$q->execute(['id'=>$examId]);if(!(int)$q->fetchColumn())throw new RuntimeException('Add at least one subject assessment before approving.');
                    $q=$pdo->prepare("UPDATE results r JOIN assessments a ON a.id=r.assessment_id SET r.status='approved' WHERE a.examination_id=:id AND r.status='submitted'");$q->execute(['id'=>$examId]);
                }
                if($to==='published'){
                    if($from!=='approved')throw new RuntimeException('Approve results before publication.');
                    $q=$pdo->prepare("SELECT COUNT(*) FROM assessments a JOIN examinations e ON e.id=a.examination_id JOIN terms t ON t.id=e.term_id WHERE a.examination_id=:id AND (SELECT COUNT(*) FROM enrollments en JOIN students st ON st.id=en.student_id WHERE en.class_group_id=a.class_group_id AND en.academic_year_id=t.academic_year_id AND en.status='active' AND st.status='active')<>(SELECT COUNT(*) FROM results r WHERE r.assessment_id=a.id AND r.status='approved')");$q->execute(['id'=>$examId]);if((int)$q->fetchColumn())throw new RuntimeException('All active students must have approved marks before publication.');
                    $q=$pdo->prepare("SELECT COUNT(*) FROM assessments WHERE examination_id=:id");$q->execute(['id'=>$examId]);if(!(int)$q->fetchColumn())throw new RuntimeException('Add at least one subject assessment before publication.');
                    $q=$pdo->prepare("UPDATE results r JOIN assessments a ON a.id=r.assessment_id SET r.status='published' WHERE a.examination_id=:id AND r.status='approved'");$q->execute(['id'=>$examId]);
                    $q=$pdo->prepare('SELECT e.name exam_name,e.type,t.id term_id,t.name term_name,y.id year_id,y.name year_name FROM examinations e JOIN terms t ON t.id=e.term_id JOIN academic_years y ON y.id=t.academic_year_id WHERE e.id=:id');$q->execute(['id'=>$examId]);$examData=$q->fetch();
                    $brand=$pdo->query('SELECT name,motto,address,phone,email,website,currency FROM school_profile ORDER BY id LIMIT 1')->fetch()?:['name'=>'School Management','motto'=>null,'address'=>null,'phone'=>null,'email'=>null,'website'=>null,'currency'=>'TZS'];
                    $students=$pdo->prepare("SELECT DISTINCT r.student_id,s.admission_number,s.full_name,c.id class_group_id,c.name class_name FROM results r JOIN assessments a ON a.id=r.assessment_id JOIN students s ON s.id=r.student_id JOIN class_groups c ON c.id=a.class_group_id WHERE a.examination_id=:exam AND r.status='published' ORDER BY s.full_name");$students->execute(['exam'=>$examId]);$publishedStudents=$students->fetchAll();
                    $items=$pdo->prepare('SELECT su.code,su.name subject_name,r.mark,a.max_mark,rv.grade,rv.comments FROM results r JOIN assessments a ON a.id=r.assessment_id JOIN subjects su ON su.id=a.subject_id LEFT JOIN result_versions rv ON rv.result_id=r.id AND rv.version=r.current_version WHERE a.examination_id=:exam AND r.student_id=:student AND r.status=\'published\' ORDER BY su.name');
                    $findReport=$pdo->prepare('SELECT id FROM report_cards WHERE examination_id=:exam AND student_id=:student LIMIT 1');$insertReport=$pdo->prepare('INSERT INTO report_cards (student_id,term_id,examination_id,report_number,verification_token_hash,published_at) VALUES (:student,:term,:exam,:number,:token,UTC_TIMESTAMP())');$insertSnapshot=$pdo->prepare('INSERT INTO report_card_snapshots (report_card_id,payload_json,branding_snapshot_json,checksum) VALUES (:report,:payload,:brand,:checksum)');
                    foreach($publishedStudents as $publishedStudent){$findReport->execute(['exam'=>$examId,'student'=>(int)$publishedStudent['student_id']]);if($findReport->fetchColumn())continue;$items->execute(['exam'=>$examId,'student'=>(int)$publishedStudent['student_id']]);$subjectRows=$items->fetchAll();$earned=0.0;$possible=0.0;foreach($subjectRows as $subjectRow){$earned+=(float)$subjectRow['mark'];$possible+=(float)$subjectRow['max_mark'];}$payload=['student'=>['id'=>(int)$publishedStudent['student_id'],'name'=>$publishedStudent['full_name'],'admission_number'=>$publishedStudent['admission_number'],'class_group_id'=>(int)$publishedStudent['class_group_id'],'class'=>$publishedStudent['class_name']],'academic_year'=>['id'=>(int)$examData['year_id'],'name'=>$examData['year_name']],'term'=>['id'=>(int)$examData['term_id'],'name'=>$examData['term_name']],'examination'=>['id'=>$examId,'name'=>$examData['exam_name'],'type'=>$examData['type']],'results'=>$subjectRows,'total_mark'=>$earned,'maximum_mark'=>$possible,'average_percentage'=>$possible>0?round($earned*100/$possible,2):null,'published_at'=>gmdate('c')];$payloadJson=json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$brandJson=json_encode($brand,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$insertReport->execute(['student'=>(int)$publishedStudent['student_id'],'term'=>(int)$examData['term_id'],'exam'=>$examId,'number'=>'RC-'.$examId.'-'.(int)$publishedStudent['student_id'],'token'=>hash('sha256',random_bytes(32))]);$reportId=(int)$pdo->lastInsertId();$insertSnapshot->execute(['report'=>$reportId,'payload'=>$payloadJson,'brand'=>$brandJson,'checksum'=>hash('sha256',$payloadJson.$brandJson)]);}
                }
                $q=$pdo->prepare('UPDATE examinations SET workflow_status=:status WHERE id=:id');$q->execute(['status'=>$to,'id'=>$examId]);(new AuditService())->record((int)$user['id'],'assessment.status.'.$to,'examinations',$examId,['from'=>$from]);
            });$flash='Assessment status updated to '.str_replace('_',' ',$to).'.';
        } else throw new RuntimeException('That academic action is unavailable for your account.');
    } catch(Throwable $exception) { $error=$exception instanceof PDOException?'That record conflicts with existing school data. Review the values and try again.':$exception->getMessage(); }
    if($flash!==''){school_flash('success',$flash);header('Location: '.SCHOOL_BASE_URL.'academics/index.php');exit;}
}
$terms=$pdo->query("SELECT t.id,t.name,t.status,y.name year_name FROM terms t JOIN academic_years y ON y.id=t.academic_year_id ORDER BY y.starts_on DESC,t.starts_on DESC")->fetchAll();
$exams=$pdo->query("SELECT e.id,e.name,e.type,e.workflow_status,t.name term_name,y.name year_name,(SELECT COUNT(*) FROM assessments a WHERE a.examination_id=e.id) assessment_count,(SELECT COUNT(*) FROM results r JOIN assessments a ON a.id=r.assessment_id WHERE a.examination_id=e.id) result_count FROM examinations e JOIN terms t ON t.id=e.term_id JOIN academic_years y ON y.id=t.academic_year_id ORDER BY y.starts_on DESC,t.starts_on DESC,e.id DESC")->fetchAll();
$subjects=$pdo->query('SELECT id,code,name FROM subjects WHERE active=1 ORDER BY name')->fetchAll();$classes=$pdo->query('SELECT c.id,c.name,y.name year_name,y.id year_id FROM class_groups c JOIN academic_years y ON y.id=c.academic_year_id ORDER BY y.starts_on DESC,c.name')->fetchAll();
$assessmentRows=$pdo->query("SELECT a.id,a.max_mark,e.name exam_name,e.workflow_status,s.name subject_name,c.name class_name FROM assessments a JOIN examinations e ON e.id=a.examination_id JOIN subjects s ON s.id=a.subject_id JOIN class_groups c ON c.id=a.class_group_id ORDER BY a.id DESC")->fetchAll();
if(in_array($role,['class_teacher','subject_teacher'],true)){$q=$pdo->prepare("SELECT a.id FROM assessments a JOIN examinations e ON e.id=a.examination_id JOIN terms t ON t.id=e.term_id JOIN teacher_assignments ta ON ta.class_group_id=a.class_group_id AND ta.subject_id=a.subject_id AND ta.academic_year_id=t.academic_year_id JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=:user AND st.employment_status='active' AND ta.ended_at IS NULL");$q->execute(['user'=>(int)$user['id']]);$allowedIds=array_fill_keys(array_map('intval',array_column($q->fetchAll(),'id')),true);$assessmentRows=array_values(array_filter($assessmentRows,static fn($a)=>isset($allowedIds[(int)$a['id']])));}
$selectedId=(int)($_GET['assessment_id']??0);$selected=null;foreach($assessmentRows as $a)if((int)$a['id']===$selectedId)$selected=$a;
$resultRows=[];if($selected){$q=$pdo->prepare('SELECT s.id student_id,s.admission_number,s.full_name,r.mark,r.status FROM students s JOIN enrollments en ON en.student_id=s.id LEFT JOIN results r ON r.student_id=s.id AND r.assessment_id=:assessment WHERE en.class_group_id=(SELECT class_group_id FROM assessments WHERE id=:assessment2) AND en.academic_year_id=(SELECT t.academic_year_id FROM assessments a JOIN examinations e ON e.id=a.examination_id JOIN terms t ON t.id=e.term_id WHERE a.id=:assessment3) AND en.status=\'active\' AND s.status=\'active\' ORDER BY s.full_name');$q->execute(['assessment'=>$selectedId,'assessment2'=>$selectedId,'assessment3'=>$selectedId]);$resultRows=$q->fetchAll();}
