e($exam['name'].' · '.$exam['term_name']) ?></option><?php endif; ?></select></div><div class="col-md-4"><label class="form-label">Subject</label><select name="subject_id" class="form-select" required><option value="">Choose subject</option><?php foreach($subjects as $subject): ?><option value="<?= (int)$subject['id'] ?>"><?= e($subject['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Class</label><select name="class_group_id" class="form-select" required><option value="">Choose class</option><?php foreach($classes as $class): ?><option value="<?= (int)$class['id'] ?>"><?= e($class['year_name'].' · '.$class['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Maximum mark</label><input type="number" class="form-control" name="max_mark" min="0.01" step="0.01" value="100" required></div><div class="col-md-6"><label class="form-label">Weight</label><input type="number" class="form-control" name="weight" min="0.001" step="0.001" value="1" required></div><div class="col-12"><button class="btn btn-outline-primary btn-sm"><i class="bi bi-plus-lg me-1"></i>Add subject</button></div></form></div></div></div></div><?php endif; ?>
<div class="card mb-3"><div class="card-header"><span class="card-title-sm"><i class="bi bi-journal-check me-1"></i>Assessment register</span></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Assessment</th><th>Term</th><th>Status</th><th>Subjects</th><th>Marks</th><th>Workflow</th></tr></thead><tbody><?php foreach($exams as $exam): ?><tr><td><strong><?= e($exam['name']) ?></strong><div class="small text-muted"><?= e($exam['type']) ?></div></td><td><?= e($exam['year_name'].' · '.$exam['term_name']) ?></td><td><span class="badge bg-light text-dark"><?= e(str_replace('_',' ',$exam['workflow_status'])) ?></span></td><td><?= (int)$exam['assessment_count'] ?></td><td><?= (int)$exam['result_count'] ?></td><td><div class="d-flex flex-wrap gap-1"><?php if($mayConfigure&&$exam['workflow_status']==='draft'): ?><form method="post"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="transition_exam"><input type="hidden" name="examination_id" value="<?= (int)$exam['id'] ?>"><input type="hidden" name="to_status" value="open"><button class="btn btn-sm btn-outline-success">Open</button></form><?php endif; ?><?php if($mayReview&&in_array($exam['workflow_status'],['open','under_review'],true)): ?><form method="post"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="transition_exam"><input type="hidden" name="examination_id" value="<?= (int)$exam['id'] ?>"><input type="hidden" name="to_status" value="under_review"><button class="btn btn-sm btn-outline-primary">Review</button></form><?php endif; ?><?php if($mayApprove&&$exam['workflow_status']==='under_review'): ?><form method="post"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="transition_exam"><input type="hidden" name="examination_id" value="<?= (int)$exam['id'] ?>"><input type="hidden" name="to_status" value="approved"><button class="btn btn-sm btn-outline-success">Approve</button></form><?php endif; ?><?php if($mayPublish&&$exam['workflow_status']==='approved'): ?><form method="post"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="transition_exam"><input type="hidden" name="examination_id" value="<?= (int)$exam['id'] ?>"><input type="hidden" name="to_status" value="published"><button class="btn btn-sm btn-primary">Publish</button></form><?php endif; ?></div></td></tr><?php endforeach; ?><?php if(!$exams): ?><tr><td colspan="6" class="text-center text-muted py-4">No assessments have been set up yet.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card"><div class="card-header"><span class="card-title-sm"><i class="bi bi-pencil-square me-1"></i>Marks register</span></div><div class="card-body"><form method="get" class="row g-2 align-items-end mb-3"><div class="col-md-9"><label class="form-label">Class subject assessment</label><select class="form-select" name="assessment_id" required><option value="">Choose assessment</option><?php foreach($assessmentRows as $assessment): ?><option value="<?= (int)$assessment['id'] ?>" <?= $selectedId===(int)$assessment['id']?'selected':'' ?>><?= e($assessment['exam_name'].' · '.$assessment['class_name'].' · '.$assessment['subject_name'].' ('.$assessment['workflow_status'].')') ?></option><?php endforeach; ?></select></div><div class="col-md-3"><button class="btn btn-outline-primary w-100">Load register</button></div></form>
<?php if($selected): ?><div class="d-flex justify-content-between align-items-center mb-2"><div><strong><?= e($selected['exam_name'].' · '.$selected['class_name'].' · '.$selected['subject_name']) ?></strong><div class="small text-muted">Maximum mark: <?= e(num($selected['max_mark'])) ?></div></div></div><?php if($mayEnter&&$selected['workflow_status']==='open'): ?><form method="post"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="save_marks"><input type="hidden" name="assessment_id" value="<?= (int)$selectedId ?>"><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>Admission number</th><th>Student</th><th>Mark / <?= e(num($selected['max_mark'])) ?></th><th>Status</th></tr></thead><tbody><?php foreach($resultRows as $row): ?><tr><td><?= e($row['admission_number']) ?></td><td><?= e($row['full_name']) ?></td><td><input class="form-control form-control-sm" type="number" name="marks[<?= (int)$row['student_id'] ?>]" min="0" max="<?= e($selected['max_mark']) ?>" step="0.01" value="<?= e($row['mark']??'') ?>" required></td><td><?= e($row['status']??'not entered') ?></td></tr><?php endforeach; ?><?php if(!$resultRows): ?><tr><td colspan="4" class="text-center text-muted py-3">No active students are enrolled in this class.</td></tr><?php endif; ?></tbody></table></div><?php if($resultRows): ?><button class="btn btn-primary btn-sm"><i class="bi bi-send me-1"></i>Save and submit marks</button><?php endif; ?></form><?php else: ?><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Admission</th><th>Student</th><th>Mark</th><th>Status</th></tr></thead><tbody><?php foreach($resultRows as $row): ?><tr><td><?= e($row['admission_number']) ?></td><td><?= e($row['full_name']) ?></td><td><?= $row['mark']===null?'—':e(num($row['mark'])) ?></td><td><?= e($row['status']??'not entered') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php else: ?><p class="text-muted mb-0">Choose an assessment to open its class register.</p><?php endif; ?></div></div>
